CREATE OR REPLACE FUNCTION public.metrics_telegram_snapshot(_actor uuid,_scope jsonb DEFAULT '{}') RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ DECLARE audience text;BEGIN SELECT role::text INTO audience FROM public.user_roles WHERE user_id=_actor AND is_active AND role IN('admin','manager','investor','leasing_manager','accountant','control') ORDER BY CASE role WHEN 'admin' THEN 0 WHEN 'manager' THEN 1 WHEN 'investor' THEN 2 WHEN 'leasing_manager' THEN 3 WHEN 'accountant' THEN 4 ELSE 5 END LIMIT 1;IF audience IS NULL THEN RAISE EXCEPTION 'الحساب غير مسموح له بالتقارير';END IF;RETURN public._metrics_snapshot(_scope,audience);END $$;
REVOKE ALL ON FUNCTION public.metrics_telegram_snapshot(uuid,jsonb) FROM PUBLIC,anon,authenticated;GRANT EXECUTE ON FUNCTION public.metrics_telegram_snapshot(uuid,jsonb) TO service_role;
SELECT has_function_privilege('authenticated','public.metrics_telegram_snapshot(uuid,jsonb)','EXECUTE') AS actor_spoofing_must_be_false;